function facultyPickerHtml(e){const checked=id=>e.facultyIds?.includes(id)?'checked':'';return `<details class="cb-faculty-picker"><summary>${esc(facultySummary(e))}</summary><div class="cb-faculty-menu"><label><input type="checkbox" data-fid="__all__" ${checked('__all__')}> All Faculty</label><label><input type="checkbox" data-fid="__coordinator__" ${checked('__coordinator__')}> Course Coordinator(s)</label>${state.faculty.map(f=>`<label><input type="checkbox" data-fid="${esc(f.id)}" ${checked(f.id)}> ${esc(f.short)}</label>`).join('')}</div></details>`}
function bindFacultyPicker(tr,e){tr.querySelectorAll('.cb-faculty-picker input').forEach(ch=>ch.onchange=()=>{let ids=[...tr.querySelectorAll('.cb-faculty-picker input:checked')].map(x=>x.dataset.fid);if(ch.checked&&['__all__','__coordinator__'].includes(ch.dataset.fid))ids=[ch.dataset.fid];else if(ch.checked)ids=ids.filter(x=>!['__all__','__coordinator__'].includes(x));e.facultyIds=[...new Set(ids)];renderTable()})}
function renderTablePreserve(eventId,selector){const active=document.activeElement,selStart=(active&&typeof active.selectionStart==='number')?active.selectionStart:null,selEnd=(active&&typeof active.selectionEnd==='number')?active.selectionEnd:null;renderTable();requestAnimationFrame(()=>{const tr=[...document.querySelectorAll('tr[data-event-id]')].find(r=>r.dataset.eventId===eventId),el=tr?.querySelector(selector);if(!el)return;el.focus();if(selStart!==null&&typeof el.setSelectionRange==='function')try{el.setSelectionRange(Math.min(selStart,el.value.length),Math.min(selEnd??selStart,el.value.length))}catch{}})}
function buildEventRow(e){const issues=eventIssues(e),tr=document.createElement('tr');tr.dataset.eventId=e.id;if(issues.length)tr.classList.add('cb-row-warning');if(!e.include)tr.classList.add('cb-row-excluded');const issueLabel=x=>x==='faculty'?'Assign faculty':x==='weekday'?`Printed ${e.day}, but ${e.date} is a ${dayFromDate(e.date)}`:x==='inferred-time'?'Confirm inferred time':x==='continuation-row'?'Verify inherited date':x==='date-order'?'Date earlier than row above':x==='year'?'Year differs from nearby dates':`Check ${x}`,dateIssue=['weekday','continuation-row','year','date-order'].some(x=>issues.includes(x)),statusText=issues.length?`<span class="ft-status-warning">! ${issues.map(issueLabel).join(', ')}</span>`:(!e.include?'<span class="ft-muted">Excluded</span>':'<span class="ft-status-ready">✓ Ready</span>'),status=`${statusText}${dateIssue?`<div style="margin-top:7px"><button type="button" class="ft-btn ev-confirm-date" style="padding:7px 10px">Confirm date</button></div>`:''}`,timeNote=e.timeSource==='inferred'?`<div class="cb-time-source ${e.timeConfirmed?'confirmed':'inferred'}">${e.timeConfirmed?'✓ Recurring schedule confirmed':'! From recurring schedule'}</div>`:'',dateNote=e.dateConfirmed?'<div class="cb-time-source confirmed">✓ Date confirmed</div>':'';tr.innerHTML=`<td><input class="cb-checkbox ev-include" type="checkbox" ${e.include?'checked':''} aria-label="Include ${esc(e.topic)}"></td><td><input class="ft-input cb-inline-input ev-date" value="${esc(e.date)}">${dateNote}</td><td><input class="ft-input cb-inline-input ev-time" value="${esc(e.time)}">${timeNote}</td><td><input class="ft-input cb-topic-input ev-topic" value="${esc(e.topic)}">${e.reading?`<div class="ft-muted" style="font-size:12px;margin-top:4px">${esc(e.reading)}</div>`:''}</td><td>${facultyPickerHtml(e)}</td><td><input class="ft-input cb-inline-input ev-location" value="${esc(e.location)}"></td><td>${status}</td><td class="cb-action-cell"><button class="cb-link-btn ev-delete" title="Delete event">Delete</button></td>`;tr.querySelector('.ev-include').onchange=x=>{e.include=x.target.checked;renderTable()};tr.querySelector('.ev-date').onchange=x=>{e.date=normalizeDate(x.target.value);e.dateConfirmed=false;e.dateWarning='';renderTablePreserve(e.id,'.ev-date')};tr.querySelector('.ev-time').onchange=x=>{e.time=normalizeDashes(x.target.value);e.timeSource=e.time?'explicit':'missing';e.timeConfirmed=!!e.time;renderTablePreserve(e.id,'.ev-time')};tr.querySelector('.ev-topic').onchange=x=>{e.topic=clean(x.target.value);e.type=classify(e.topic);renderTablePreserve(e.id,'.ev-topic')};tr.querySelector('.ev-location').onchange=x=>{e.location=clean(x.target.value);e.locationSource=e.location?'explicit':'missing'};bindFacultyPicker(tr,e);const confirmDate=tr.querySelector('.ev-confirm-date');if(confirmDate)confirmDate.onclick=()=>{const calendarDay=dayFromDate(e.date);if(!calendarDay){showToast('Enter a valid date before confirming it.',true);return}e.dateConfirmed=true;e.day=calendarDay;renderTable();showToast(`${e.type==='assessment'?'Assessment':'Event'} date confirmed.`)};tr.querySelector('.ev-delete').onclick=()=>{state.events=state.events.filter(v=>v.id!==e.id);renderTable()};return tr}
function renderTable(){const reviewBody=$('reviewBody'),body=$('scheduleBody');reviewBody.innerHTML='';body.innerHTML='';const needs=state.events.filter(e=>eventIssues(e).length);needs.forEach(e=>reviewBody.appendChild(buildEventRow(e)));$('reviewSectionCount').textContent=needs.length;$('reviewTableWrap').classList.toggle('cb-hidden',!needs.length);$('reviewEmpty').classList.toggle('is-visible',!needs.length);const f=$('filterFaculty').value,q=$('searchEvents').value.toLowerCase();state.events.filter(e=>!eventIssues(e).length).filter(e=>{const ids=e.facultyIds||[],ok=f==='all'||ids.includes(f)||(f==='assessment'&&['assessment','activity'].includes(e.type))||(f==='Excluded'&&!e.include);return ok&&e.topic.toLowerCase().includes(q)}).forEach(e=>body.appendChild(buildEventRow(e)));updateMetrics()}
function lectureCompleteness(){const eligible=state.events.filter(e=>e.lectureSource==='header');if(!eligible.length)return null;const nums=eligible.map(e=>/^\d+$/.test(e.lecture)?+e.lecture:null).filter(Number.isFinite);if(nums.length<3)return null;const max=Math.max(...nums),set=new Set(nums),missing=[];for(let i=1;i<=max;i++)if(!set.has(i))missing.push(i);const dup=[...new Set(nums.filter((n,i,a)=>a.indexOf(n)!==i))];return{max,missing,dup}}
function updateMetrics(){$('metricEvents').textContent=state.events.length;$('metricFaculty').textContent=state.faculty.length;$('metricReview').textContent=state.events.filter(e=>eventIssues(e).some(x=>x!=='inferred-time')).length;$('metricIncluded').textContent=state.events.filter(e=>e.include).length;$('metricInferred').textContent=state.events.filter(e=>e.timeSource==='inferred').length;const c=lectureCompleteness(),box=$('completenessNotice');if(!c){box.innerHTML='';return}if(c.missing.length||c.dup.length){box.className='ft-notice ft-notice-warning cb-completeness';box.innerHTML=`<strong>! Schedule completeness check</strong><br><span class="ft-muted">${c.missing.length?`Lecture number${c.missing.length===1?'':'s'} ${c.missing.join(', ')} ${c.missing.length===1?'was':'were'} not detected. `:''}${c.dup.length?`Duplicate lecture number${c.dup.length===1?'':'s'}: ${c.dup.join(', ')}.`:''} Review the source schedule before export.</span>`}else{box.className='ft-notice ft-notice-success cb-completeness';box.innerHTML=`<strong>✓ Lecture sequence appears complete</strong><br><span class="ft-muted">CalendarBridge detected lecture numbers 1–${c.max} without gaps.</span>`}}
function refreshFacultyOptions(){const sel=$('filterFaculty'),cur=sel.value;sel.innerHTML=`<option value="all">All events</option>${state.faculty.map(f=>`<option value="${esc(f.id)}">${esc(f.short)}</option>`).join('')}<option value="assessment">Assessments & activities</option><option value="Excluded">Excluded</option>`;if([...sel.options].some(o=>o.value===cur))sel.value=cur}
function renderFacultyEditor(){ensureV6State();const box=$('facultyEditor');box.innerHTML='';state.faculty.forEach((f,i)=>{const isCoord=(state.coordinatorIds||[]).includes(f.id);const row=document.createElement('div');row.className='cb-faculty-edit-row';const role=isCoord?'Course Coordinator':'Course Faculty';row.innerHTML=`<div class="ft-field"><label>${role}</label><input class="ft-input f-short" value="${esc(f.short)}"></div><div class="ft-field"><label>Name</label><input class="ft-input f-name" value="${esc(f.name)}"></div><div class="ft-field"><label>Email</label><input class="ft-input f-email" type="email" value="${esc(f.email)}"></div><div class="cb-btn-row"><button class="ft-btn f-coordinator">${isCoord?'Remove coordinator role':'Add coordinator'}</button><button class="ft-btn ft-btn-danger f-remove">Remove</button></div>`;row.querySelector('.f-short').onchange=x=>{f.short=clean(x.target.value)||`Faculty ${i+1}`;refreshFacultyOptions();renderTable()};row.querySelector('.f-name').onchange=x=>{f.name=clean(x.target.value);renderTable()};row.querySelector('.f-email').onchange=x=>f.email=clean(x.target.value);row.querySelector('.f-coordinator').onclick=()=>{const ids=new Set(state.coordinatorIds||[]);if(isCoord)ids.delete(f.id);else ids.add(f.id);state.coordinatorIds=[...ids];state.coordinatorId=state.coordinatorIds[0]||null;renderFacultyEditor();renderTable();renderExportSummary();showToast(isCoord?`${f.short||f.name||'Faculty member'} removed as course coordinator.`:`${f.short||f.name||'Faculty member'} added as course coordinator.`)};row.querySelector('.f-remove').onclick=()=>{state.events.forEach(e=>e.facultyIds=(e.facultyIds||[]).filter(id=>id!==f.id));state.faculty=state.faculty.filter(v=>v.id!==f.id);state.coordinatorIds=(state.coordinatorIds||[]).filter(id=>id!==f.id);state.coordinatorId=state.coordinatorIds[0]||null;renderFacultyEditor();refreshFacultyOptions();renderTable()};box.appendChild(row)})}

function splitPatternParts(value){
 const raw=normalizeDashes(clean(value).replace(/\./g,':'));
 const m=raw.match(/^\s*(\d{1,2}:\d{2})\s*(AM|PM)?\s*–\s*(\d{1,2}:\d{2})\s*(AM|PM)?\s*$/i);
 if(!m)return{start:'',startMer:'',end:'',endMer:''};
 let startMer=(m[2]||'').toUpperCase(),endMer=(m[4]||'').toUpperCase();
 if(!startMer&&endMer)startMer=endMer;
 if(!endMer&&startMer)endMer=startMer;
 return{start:m[1],startMer,end:m[3],endMer};
}
function periodString(p){
 const start=clean(p?.start),end=clean(p?.end),sm=clean(p?.startMer).toUpperCase(),em=clean(p?.endMer).toUpperCase();
 if(!start&&!end)return'';
 return clean(`${start}${sm?' '+sm:''} – ${end}${em?' '+em:''}`);
}
function renderMeetingPatterns(){
  const host=$('meetingPatternEditor');
  if(!host)return;
  const days=['Monday','Tuesday','Wednesday','Thursday','Friday'];
  host.innerHTML='';
  const missing=[];
  days.forEach(day=>{
    const vals=state.meetingPatterns?.[day]||[];
    if(!vals.length&&!expandedMeetingDays.has(day)){missing.push(day);return}
    const wrap=document.createElement('div');
    wrap.className='cb-meeting-day';
    const periods=(vals.length?vals.map(splitPatternParts):[{start:'',startMer:'',end:'',endMer:''}]);
    wrap.innerHTML=`<strong>${day}</strong><div class="periodHost"></div><button type="button" class="ft-btn cb-add-period">+ Add period</button><div class="cb-pattern-source">${vals.length?`${vals.length} detected period${vals.length===1?'':'s'}${periods.some(p=>!p.startMer||!p.endMer)?' · AM/PM needed':''}`:'Manual period — enter start/end time'}</div>`;
    const ph=wrap.querySelector('.periodHost');
    const save=()=>{state.meetingPatterns[day]=periods.map(periodString).filter(Boolean)};
    const draw=()=>{
      ph.innerHTML='';
      periods.forEach((p,i)=>{
        const row=document.createElement('div');
        row.className='cb-period-row';
        row.innerHTML=`<div class="cb-time-line"><span class="cb-time-label">Start</span><input class="ft-input p-start" aria-label="${day} start time" placeholder="9:40" value="${esc(p.start)}"><button type="button" class="ft-btn cb-meridiem p-sm">${p.startMer||'AM/PM'}</button></div><div class="cb-time-line"><span class="cb-time-label">End</span><input class="ft-input p-end" aria-label="${day} end time" placeholder="10:40" value="${esc(p.end)}"><button type="button" class="ft-btn cb-meridiem p-em">${p.endMer||'AM/PM'}</button></div><button type="button" class="ft-btn cb-period-remove" aria-label="Remove ${day} period">×</button>`;
        row.querySelector('.p-start').onchange=e=>{p.start=clean(e.target.value);save()};
        row.querySelector('.p-end').onchange=e=>{p.end=clean(e.target.value);save()};
        const toggle=(key,btn)=>{p[key]=p[key]==='AM'?'PM':'AM';btn.textContent=p[key];save()};
        row.querySelector('.p-sm').onclick=e=>toggle('startMer',e.currentTarget);
        row.querySelector('.p-em').onclick=e=>toggle('endMer',e.currentTarget);
        row.querySelector('.cb-period-remove').onclick=()=>{
          periods.splice(i,1);save();
          if(!periods.length){expandedMeetingDays.delete(day);renderMeetingPatterns();return}
          draw();
        };
        ph.appendChild(row)
      })
    };
    draw();
    wrap.querySelector('.cb-add-period').onclick=()=>{periods.push({start:'',startMer:'',end:'',endMer:''});draw()};
    host.appendChild(wrap)
  });
  if(missing.length){
    const collapsed=document.createElement('div');
    collapsed.className='cb-undetected-days';
    collapsed.innerHTML='<span class="cb-undetected-label">Not detected:</span>';
    missing.forEach(day=>{
      const btn=document.createElement('button');
      btn.type='button';btn.className='cb-day-pill';
      btn.setAttribute('aria-label',`Add recurring ${day} period`);
      btn.innerHTML=`<span>+ ${day}</span><span class="cb-day-pill-note">add period</span>`;
      btn.onclick=()=>{expandedMeetingDays.add(day);renderMeetingPatterns()};
      collapsed.appendChild(btn)
    });
    host.appendChild(collapsed)
  }
}
async function applyMeetingPatterns(){state.meetingLocation=clean($('meetingLocation').value);const validSlots=Object.values(state.meetingPatterns||{}).flat().filter(Boolean),invalid=validSlots.filter(v=>!parseTimeRange(v));if(invalid.length){FTDialog.alert('Choose AM or PM for every recurring start and end time, then apply the schedule again.',{title:'Times need AM or PM'});return}const affected=state.events.filter(e=>e.include&&e.type!=='assessment'&&state.meetingPatterns?.[e.day||dayFromDate(e.date)]?.length).length;if(!await FTDialog.confirm(`This will replace the start and end times for ${affected} matching non-assessment event${affected===1?'':'s'} in the detailed schedule. Explicit special-event times such as exams are preserved.\n\nThe recurring location will also be applied when one is entered.`,{title:'Apply the course schedule?',confirmLabel:'Apply schedule'}))return;if(state.meetingLocation){state.events.forEach(e=>{if(e.include&&e.type!=='no-class'){e.location=state.meetingLocation;e.locationSource='confirmed-schedule'}})}const byDate={};state.events.forEach(e=>{if(!e.include||e.type==='assessment'||e.type==='no-class')return;if(!e.day)e.day=dayFromDate(e.date);if(!e.day)return;(byDate[e.date]??=[]).push(e)});for(const evs of Object.values(byDate)){const day=evs[0].day||dayFromDate(evs[0].date),slots=state.meetingPatterns?.[day]||[];if(!slots.length)continue;evs.forEach((e,i)=>{const slot=slots[Math.min(i,slots.length-1)];if(slot&&parseTimeRange(slot)){e.time=slot;e.timeSource='confirmed-schedule';e.timeConfirmed=true}})}renderTable();showToast('High-level schedule confirmed and applied. Review the detailed schedule before export.')}
function renderRevisionPanel(){const panel=$('revisionPanel');if(!panel)return;if(!state.revision){panel.classList.remove('is-visible');return}panel.classList.add('is-visible');const c=state.revision.counts||{};$('revAdded').textContent=c.added||0;$('revChanged').textContent=c.changed||0;$('revRemoved').textContent=c.removed||0;$('revUnchanged').textContent=c.unchanged||0;$('revisionSummary').textContent=`Compared ${state.revision.baseSource||'saved project'} with ${state.revision.currentSource||state.sourceName}.`;if($('downloadRemovedReport'))$('downloadRemovedReport').disabled=!(state.revision.removed||[]).length}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
function go(step){['upload','review','faculty','export'].forEach(s=>$('screen-'+s).classList.toggle('is-active',s===step));document.querySelectorAll('.ft-step').forEach(b=>{const order=['upload','review','faculty','export'],s=b.dataset.step;b.classList.toggle('is-active',s===step);b.classList.toggle('is-done',order.indexOf(s)<order.indexOf(step))});if(step==='faculty')renderFaculty();if(step==='export')renderExportSummary();window.scrollTo({top:0,behavior:'smooth'})}
