function showLoading(on,text='',pct=0){$('loadingState').classList.toggle('is-visible',on);if(text)$('loadingText').textContent=text;$('progressBar').style.width=`${pct}%`;['chooseFile','loadSample'].forEach(id=>$(id).disabled=on)}
let toastTimer;function showToast(msg,error=false){clearTimeout(toastTimer);const t=$('toast');t.textContent=msg;t.style.background=error?'var(--ft-danger)':'var(--ft-text)';t.style.color=error?'#fff':'var(--ft-surface)';t.style.opacity=1;t.style.transform='none';toastTimer=setTimeout(()=>{t.style.opacity=0;t.style.transform='translateY(15px)'},3000)}
function buildIcs(events,calName){const stamp=icsStamp(new Date()),lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Faculty Tools//CalendarBridge v7.5.9//EN','CALSCALE:GREGORIAN','METHOD:PUBLISH',`X-WR-CALNAME:${icsEscape(calName)}`,`X-WR-TIMEZONE:${CALENDAR_TIME_ZONE.id}`,...CALENDAR_TIME_ZONE.vtimezone];for(const e of events){const d=parseDateParts(e.date),t=parseTimeRange(e.time);if(!d||!t)continue;const desc=[e.lecture?`Lecture: ${e.lecture}`:'',e.reading?`Related reading: ${e.reading}`:'',`Instructor: ${facultySummary(e)}`,`Source: ${state.sourceName}`].filter(Boolean).join('\n');lines.push('BEGIN:VEVENT',`UID:${e.stableUid||`cb-${hashText(`${state.course.code}|${e.lecture}|${e.topic}`)}`}@calendarbridge.facultytools`,`DTSTAMP:${stamp}`,`SEQUENCE:${eventSequence(e)}`,`DTSTART;TZID=${CALENDAR_TIME_ZONE.id}:${dateTimeStamp(d,t.start)}`,`DTEND;TZID=${CALENDAR_TIME_ZONE.id}:${dateTimeStamp(d,t.end)}`,`SUMMARY:${icsEscape(`${state.course.code} – ${state.course.title}: ${e.topic}`)}`,`LOCATION:${icsEscape(e.location||state.course.location)}`,`DESCRIPTION:${icsEscape(desc)}`,'STATUS:CONFIRMED','TRANSP:OPAQUE','END:VEVENT')}lines.push('END:VCALENDAR');return lines.join('\r\n')+'\r\n'}
function compareProjects(base,newState){const oldEvents=(base.events||[]),newEvents=(newState.events||[]),oldMap=new Map();oldEvents.forEach(e=>{const k=eventCompareKey(e);if(!oldMap.has(k))oldMap.set(k,[]);oldMap.get(k).push(e)});const matched=new Set(),counts={added:0,changed:0,removed:0,unchanged:0};newEvents.forEach(ne=>{const bucket=oldMap.get(eventCompareKey(ne))||[];let old=bucket.find(x=>!matched.has(x.id));if(!old){ne.revisionStatus='added';counts.added++;return}pairRevisedEvent(old,ne,matched,counts)});newEvents.filter(e=>e.revisionStatus==='added').forEach(ne=>{const old=ne.stableUid&&oldEvents.find(x=>!matched.has(x.id)&&x.stableUid===ne.stableUid);if(!old)return;counts.added--;pairRevisedEvent(old,ne,matched,counts)});const usedUids=new Set([...oldEvents,...newEvents.filter(e=>e.revisionStatus!=='added')].map(e=>e.stableUid).filter(Boolean));newEvents.filter(e=>e.revisionStatus==='added').forEach(e=>{e.sequence=0;e.stableUid=uniqueUid(e.stableUid,usedUids)});const removed=oldEvents.filter(e=>!matched.has(e.id)).map(e=>({...structuredClone(e),revisionStatus:'removed'}));counts.removed=removed.length;newState.revision={active:true,comparedAt:new Date().toISOString(),baseSource:base.sourceName,currentSource:newState.sourceName,counts,removed};return newState}
async function compareRevisionFile(file){if(!file?.name?.toLowerCase().endsWith('.docx')){showToast('Please choose the revised .docx syllabus.',true);return}showLoading(true,'Reading revised Word syllabus…',15);const base=structuredClone(state);try{const parsed=await parseDocx(file);state=parsed;resolveEventYears();flagDateProblems();inferMissingTimes();state.events=dedupeEvents(state.events);assignStableUids();state.sharedCalendar=structuredClone(base.sharedCalendar||{enabled:true,label:'SUSAV Pharmacy Registrar',email:'susavpharmacyregistrar@southuniversity.edu'});state=compareProjects(base,state);showLoading(false);refreshAll();go('review');showToast('Revised syllabus compared with saved project.')}catch(err){console.error(err);state=base;showLoading(false);refreshAll();showToast(err.message||'Could not compare the revised syllabus.',true)}}
function dateTimeStamp(d,t){return `${d.y}${pad(d.mo)}${pad(d.d)}T${pad(t.h)}${pad(t.min)}00`}
function downloadFacultyIcs(facultyId){if(!exportReady())return;const f=state.faculty.find(x=>x.id===facultyId);if(!f)return;const evs=getExportEvents(eventsForFaculty(f.id));if(!evs.length){showToast('No events match the selected export scope.',true);return}const text=buildIcs(evs,`${state.course.code} ${state.course.title} — ${f.short}`),blob=new Blob([text],{type:'text/calendar;charset=utf-8'});downloadBlob(blob,`${safeFile(f.short)}-${safeFile(state.course.code||'Course')}${$('exportScope')?.value==='updated'?'-Updated':''}.ics`);showToast(`${f.short} calendar downloaded.`)}
function downloadRemovedReport(){if(!state.revision?.removed?.length){showToast('No removed events were detected.');return}const lines=[`CalendarBridge v7.5.9 — Removed events report`,`Course: ${state.course.code} – ${state.course.title}`,`Compared: ${state.revision.baseSource} → ${state.revision.currentSource}`,'',...state.revision.removed.map(e=>`${e.date} | ${e.time||'Time not specified'} | ${e.topic} | ${facultySummary(e)}`)];downloadBlob(new Blob([lines.join('\r\n')],{type:'text/plain;charset=utf-8'}),`${safeFile(state.course.code||'Course')}-Removed-Events.txt`)}
