function ensureV6State(){state.coordinatorIds=Array.isArray(state.coordinatorIds)?state.coordinatorIds.filter(id=>state.faculty?.some(f=>f.id===id)):(state.coordinatorId?[state.coordinatorId]:[]);state.coordinatorId=state.coordinatorIds[0]||null;state.sharedCalendar=state.sharedCalendar||{enabled:true,label:'SUSAV Pharmacy Registrar',email:'susavpharmacyregistrar@southuniversity.edu'};if(state.sharedCalendar.enabled===undefined)state.sharedCalendar.enabled=true;state.sharedCalendar.label=state.sharedCalendar.label||'SUSAV Pharmacy Registrar';state.sharedCalendar.email=state.sharedCalendar.email||'susavpharmacyregistrar@southuniversity.edu';state.projectVersion="7.5.9";state.events=(state.events||[]).map(e=>({...e,dateConfirmed:!!e.dateConfirmed,revisionStatus:e.revisionStatus||''}))}
function eventCompareKey(e){if(clean(e.lecture))return `lecture:${clean(e.lecture).toLowerCase()}`;const d=clean(e.date),type=classify(e.topic);if(type==='assessment')return `assessment:${d}:${clean(e.topic).toLowerCase().replace(/\([^)]*\)/g,'').replace(/\d+/g,'#')}`;return `date:${d}|day:${clean(e.day).toLowerCase()}|faculty:${(e.facultyIds||[]).slice().sort().join(',')}`}
// Calendar apps treat an event with the same UID and a higher SEQUENCE as a newer version of it.
function eventSequence(e){const n=Number(e?.sequence);return Number.isInteger(n)&&n>0?n:0}
// Events without a lecture number are compared by date, so a moved event misses on the first pass;
// compareProjects then pairs it with the unmatched old event that has the same UID (same topic and type).
function pairRevisedEvent(old,ne,matched,counts){matched.add(old.id);if(old.stableUid)ne.stableUid=old.stableUid;if(eventFingerprint(old)===eventFingerprint(ne)){ne.revisionStatus='unchanged';ne.sequence=eventSequence(old);counts.unchanged++}else{ne.revisionStatus='changed';ne.previousEvent=structuredClone(old);ne.sequence=eventSequence(old)+1;counts.changed++}}
// Added events never reuse an old UID, including a removed event's, so a calendar cannot mistake them for that event.
function uniqueUid(uid,used){let out=uid,n=2;while(used.has(out))out=`${uid}-${n++}`;used.add(out);return out}
function eventFingerprint(e){return JSON.stringify({date:clean(e.date),time:clean(e.time),topic:clean(e.topic),faculty:(e.facultyIds||[]).slice().sort(),reading:clean(e.reading),location:clean(e.location),include:!!e.include})}
function eventsForFaculty(id){return state.events.filter(e=>e.include&&!eventIssues(e).length&&((e.facultyIds||[]).includes(id)||(e.facultyIds||[]).includes('__all__')||((e.facultyIds||[]).includes('__coordinator__')&&(state.coordinatorIds||[]).includes(id)))).sort(sortEvents)}
