function exportReady(){if(state.events.some(e=>eventIssues(e).length)){showToast('Resolve all Needs review events before exporting.',true);go('review');return false}return true}
function getExportEvents(events){const valid=events.filter(e=>e.include&&!eventIssues(e).length);if($('exportScope')?.value==='updated'&&state.revision)return valid.filter(e=>e.revisionStatus==='added'||e.revisionStatus==='changed');return valid}
function icsEscape(s){return String(s||'').replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;')}
function icsStamp(dt){return `${dt.getUTCFullYear()}${pad(dt.getUTCMonth()+1)}${pad(dt.getUTCDate())}T${pad(dt.getUTCHours())}${pad(dt.getUTCMinutes())}${pad(dt.getUTCSeconds())}Z`}

function fbCourseDate(iso,raw){if(iso&&/^\d{4}-\d{2}-\d{2}$/.test(iso)){const [y,m,d]=iso.split('-').map(Number);return `${m}/${d}/${y}`}return clean(raw)}
function fbTime12(hm){if(!/^\d{2}:\d{2}$/.test(clean(hm)))return'';let [h,m]=hm.split(':').map(Number),p=h>=12?'PM':'AM',hh=h%12||12;return `${hh}:${String(m).padStart(2,'0')} ${p}`}
function fbTimeRange(item){if(item.timeText)return normalizeDashes(item.timeText);if(item.startTime&&item.endTime)return `${fbTime12(item.startTime)} – ${fbTime12(item.endTime)}`;return''}
function validateFacultyBridgeCourse(obj){
 if(!obj||obj.schema!=='facultybridge.course')throw new Error('This JSON is not a FacultyBridge Course file.');
 const major=String(obj.schemaVersion||'').split('.')[0];
 if(major!=='1')throw new Error(`CalendarBridge supports FacultyBridge Course schema v1.x. This file uses ${obj.schemaVersion||'an unknown version'}.`);
 if(!obj.course||!Array.isArray(obj.schedule)||!Array.isArray(obj.faculty))throw new Error('This FacultyBridge Course file is missing required course, faculty, or schedule data.');
 return obj;
}

async function loadJsonByType(file){
 try{
  const text=await file.text(),obj=JSON.parse(text);
  if(obj?.schema==='facultybridge.course')return loadFacultyBridgeCourse(new File([text],file.name,{type:'application/json'}));
  if(obj?.course&&Array.isArray(obj.events))return loadProject(new File([text],file.name,{type:'application/json'}));
  throw new Error('This JSON is not a FacultyBridge Course file or a CalendarBridge project.');
 }catch(err){
  console.error(err);
  showUploadError(err.message||'CalendarBridge could not identify this JSON file.','JSON file could not be opened');
  showToast(err.message||'Could not open JSON file.',true);
 }
}
async function loadFacultyBridgeCourse(file){
 expandedMeetingDays.clear();
 try{
  const obj=validateFacultyBridgeCourse(JSON.parse(await file.text()));
  const faculty=(obj.faculty||[]).map((f,i)=>({id:clean(f.id)||`faculty-${i+1}`,short:clean(f.shortName)||lastNameFrom(f.name)||`Faculty ${i+1}`,name:clean(f.name),email:clean(f.email)}));
  const out={
   sourceName:obj.source?.fileName||file.name,
   course:{code:clean(obj.course.code),title:clean(obj.course.title),year:String(obj.course.year||new Date().getFullYear()),location:clean(obj.course.location)},
   faculty,coordinatorIds:(Array.isArray(obj.coordinatorIds)?obj.coordinatorIds:(obj.coordinatorId?[obj.coordinatorId]:(obj.faculty||[]).filter(x=>x.role==='coordinator').map(x=>x.id))).filter(id=>faculty.some(f=>f.id===id)),coordinatorId:null,
   events:[],
   meetingPatterns:{Monday:[],Tuesday:[],Wednesday:[],Thursday:[],Friday:[]},
   meetingLocation:clean(obj.course.location),
   sharedCalendar:{enabled:true,label:'SUSAV Pharmacy Registrar',email:'susavpharmacyregistrar@southuniversity.edu'},
   revision:null,projectVersion:"7.5.9",
   handoff:{schema:obj.schema,schemaVersion:obj.schemaVersion,producer:obj.producer||null,importedAt:new Date().toISOString()}
  };
  out.coordinatorId=out.coordinatorIds[0]||null;
  for(const m of obj.recurringSchedule||[]){const day=normalizeDay(m.day),time=fbTimeRange(m);if(day&&time&&!out.meetingPatterns[day].includes(time))out.meetingPatterns[day].push(time)}
  state=out;
  for(const x of obj.schedule||[]){
   const instructor=(x.facultyIds||[]).map(id=>faculty.find(f=>f.id===id)?.short).filter(Boolean).join(', ')||clean(x.facultyText);
   const ev=makeEvent({date:fbCourseDate(x.date,x.rawDate),time:fbTimeRange(x),topic:clean(x.title||x.topic),instructor,location:clean(x.location||obj.course.location),day:clean(x.day),confidence:'high'});
   ev.handoffId=x.id||'';
   ev.handoffType=x.type||'';
   if(['class','assessment','activity','no-class'].includes(x.type))ev.type=x.type;
   ev.sourceSchema=obj.schemaVersion;
   if(x.type==='no-class')ev.include=false;
   out.events.push(ev);
  }
  state=out;resolveEventYears();flagDateProblems();inferMissingTimes();state.events=dedupeEvents(state.events);assignStableUids();refreshAll();go('review');
  markCalendarOpened();showToast(`FacultyBridge Course JSON opened: ${state.events.length} schedule events.`);
 }catch(err){console.error(err);showUploadError(err.message||'CalendarBridge could not open this FacultyBridge Course JSON.','Course JSON could not be opened');showToast(err.message||'Could not open FacultyBridge Course JSON.',true)}
}
